def check(n):
    for m in range(1, n):
        # P(x) = x^n - x^m
        # Check if P(k) % n == 0 for k = 1, ..., n
        valid = True
        for k in range(1, n + 1):
            if (k**n - k**m) % n != 0:
                valid = False
                break
        if valid:
            return m
    return None

for n in range(2, 11):
    m = check(n)
    print(f"n={n}, m={m}")

