        m = None
        for m_val in range(1, n):
            valid = True
            for k in range(1, n + 1):
                if (k**n - k**m_val) % n != 0:
                    valid = False
                    break
            if valid:
                m = m_val
                break
        print(f"n={n}, m={m}")

